// Safety checks before anything is sent. Any failure stops the whole batch with an error,
// and because this runs before 'Respond to Webhook', MailMate shows that error.
const TEST_TO = 'REPLACE_WITH_YOUR_TEST_ADDRESS';  // your secondary inbox (MAILMATE_TEST_ADDRESS in .env)
const REAL_SENDING_ENABLED = true;                 // Step 7: real batches allowed (MailMate checks cap, window, approval)
const MAX_BATCH = 20;                              // daily cap

if (TEST_TO.startsWith('REPLACE')) throw new Error('Set TEST_TO at the top of the Explode + guard node first');
const wh = $('Webhook').first();
let payload;
try { payload = JSON.parse(wh.json.body.payload); } catch (err) { throw new Error('payload is not valid JSON'); }
const testMode = payload.test_mode === true;
// A scheduled batch carries its emails as `scheduled_emails`, so a W2 from before scheduling (which
// reads only `emails`) refuses it instead of sending it at once.
if (payload.start_at && payload.emails) throw new Error('A scheduled batch must carry scheduled_emails, not emails');
if (!payload.start_at && payload.scheduled_emails) throw new Error('scheduled_emails without a start_at');
const emails = payload.start_at ? payload.scheduled_emails : payload.emails;
if (!Array.isArray(emails) || emails.length === 0) throw new Error('No emails in the batch');
if (emails.length > MAX_BATCH) throw new Error(`Batch of ${emails.length} is larger than ${MAX_BATCH} - refused`);
if (!testMode && !REAL_SENDING_ENABLED) throw new Error('Real sending is not enabled in W2 yet (test mode only)');

// The resume: whatever name n8n gave the uploaded file, pass it on as `resume`.
const files = wh.binary || {};
const key = Object.keys(files)[0];
if (!key) throw new Error('No resume file received');
const resume = files[key];
if (resume.mimeType && resume.mimeType !== 'application/pdf') throw new Error(`Resume must be a PDF, got ${resume.mimeType}`);

// A scheduled batch: W2 holds it until start_at (MailMate checked the window, weekday and cap for then).
let startAt = '';
if (payload.start_at) {
  if (testMode) throw new Error('Test batches are never scheduled');
  const t = Date.parse(payload.start_at);
  if (isNaN(t)) throw new Error('start_at is not a date');
  if (t < Date.now() - 2 * 60 * 1000 || t > Date.now() + 4 * 24 * 3600 * 1000) {
    throw new Error('start_at must be within the next 4 days');
  }
  startAt = new Date(t).toISOString();
}

// Spacing between sends, with a floor so a bad payload can't send in a burst.
const min = Math.max(Number(payload.spacing_min_s) || 180, testMode ? 30 : 120);
const max = Math.max(Number(payload.spacing_max_s) || 420, min);

return emails.map(e => {
  const to = String(e.to || '').trim().toLowerCase();
  if (testMode && to !== TEST_TO.toLowerCase()) throw new Error(`Test mode may only send to the test address, got ${to}`);
  if (!to || !e.subject || !e.body_text || !e.body_html) throw new Error(`Email ${e.email_id} is missing to, subject, body_text or body_html`);
  return {
    json: {
      email_id: e.email_id, to, subject: e.subject, body_text: e.body_text, body_html: e.body_html,
      test_mode: testMode, batch_id: payload.batch_id, sender_name: payload.sender_name || '',
      spacing_min_s: min, spacing_max_s: max, reply_to_message_id: e.reply_to_message_id || '', start_at: startAt,
    },
    binary: { resume },
  };
});

// A follow-up = a reply in the first email's thread, addressed explicitly. First check that the
// first email really went to this recipient, so a follow-up (or a test) can't reach anyone else.
const e = $('Loop Over Items').item.json;
const original = $json;
const h = {};
for (const x of (original.payload?.headers || [])) h[String(x.name).toLowerCase()] = x.value;
const addr = s => {
  const text = String(s || '');
  const open = text.indexOf('<'), close = text.indexOf('>');
  return (open >= 0 && close > open ? text.slice(open + 1, close) : text).trim().toLowerCase();
};
if (addr(h['to']) !== e.to) throw new Error(`Follow-up ${e.email_id}: the first email went to ${addr(h['to'])}, not ${e.to}`);
if (!h['message-id']) throw new Error(`Follow-up ${e.email_id}: the first email has no Message-ID header`);

const CRLF = String.fromCharCode(13, 10);
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const word = s => '=?UTF-8?B?' + b64(s) + '?=';
const wrap = s => { const out = []; for (let i = 0; i < s.length; i += 76) out.push(s.slice(i, i + 76)); return out.join(CRLF); };
const mime = [
  'From: ' + (e.sender_name ? word(e.sender_name) + ' ' : '') + '<' + addr(h['from']) + '>',
  'To: ' + e.to,
  'Subject: ' + word(e.subject),
  'In-Reply-To: ' + h['message-id'],
  'References: ' + h['message-id'],
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  wrap(b64(e.body_html)),
].join(CRLF);
const raw = b64(mime).split('+').join('-').split('/').join('_').replace(/=+$/, '');
return { json: { raw, threadId: original.threadId } };

// n8n holds a scheduled batch while it waits. If n8n was off at the start time, it resumes the wait
// as soon as it's back: hours late, maybe at night. Then send nothing; MailMate can release the batch.
const first = $input.first().json;
const late = Date.now() - Date.parse(first.start_at);
if (late > 30 * 60 * 1000) {
  throw new Error(`Batch ${first.batch_id} would start ${Math.round(late / 60000)} min late (was n8n off?): nothing sent. ` +
                  'Sync replies in MailMate, then release the batch on 5 Send -> Batches and schedule it again.');
}
return $input.all();
